// Reproduces crates/deck-remote/tests/vectors/api-s4.json (generated by Rust
// crates/deck-remote/tests/api_s4/mod.rs): the slice-4 ops encode canonically, every new gateway
// message (feed values, replies, results, additive fields of R5 types) decodes to exactly the
// wire value, and the slice-4 class/journal/bound rules mirror Rust `Op`.

import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';

import {
  ApiDecodeError,
  checkFeed,
  checkRequest,
  decodeEvent,
  decodeReply,
  decodeWelcome,
  FEATURE_S4,
  MAX_ACTIVITY_DAYS,
  MAX_INVENTORY_LIMIT,
  MAX_TRANSFER_CHUNK,
  MAX_TRANSFER_CHUNK_B64,
  MAX_TREE_LIMIT,
  type Op,
  opAllowed,
  opClass,
  opJournaled,
  PROTOCOL,
  type Request,
  RequestBuilder,
  requestJson,
} from '../src/remote/api.ts';
import { utf8 } from '../src/remote/bytes.ts';

interface S4Vectors {
  protocol: number;
  features: string[];
  messages: { type: 'request' | 'reply' | 'event' | 'welcome'; case: string; json: string }[];
  rejected_requests: { case: string; json: string; error: string; id: number }[];
}

const vectors: S4Vectors = JSON.parse(
  readFileSync(new URL('../../crates/deck-remote/tests/vectors/api-s4.json', import.meta.url), 'utf8'),
);

function messages(type: S4Vectors['messages'][number]['type']): S4Vectors['messages'] {
  return vectors.messages.filter((m) => m.type === type);
}

test('protocol version and feature', () => {
  expect(vectors.protocol).toBe(PROTOCOL);
  expect(vectors.features).toEqual([FEATURE_S4]);
});

describe('slice-4 requests encode canonically', () => {
  for (const vector of messages('request')) {
    test(vector.case, () => {
      const request: Request = JSON.parse(vector.json);
      expect(checkRequest(request)).toBeNull();
      expect(requestJson(request)).toBe(vector.json);
      expect(request.seq !== null && request.seq !== undefined).toBe(opJournaled(request.op));
    });
  }

  test('absent optionals are written as null, nested fields in Rust order', () => {
    const live = { generation: 2, key: 'k' };
    expect(requestJson({ id: 1, op: { op: 'tree', limit: 5, filter: 'all', session: 's' } })).toBe(
      '{"id":1,"seq":null,"op":{"op":"tree","session":"s","filter":"all","cursor":null,"limit":5}}',
    );
    expect(
      requestJson({
        id: 2,
        seq: 9,
        op: {
          op: 'answer_ui',
          value: { answers: [{ selected: [1], id: 'q' }], type: 'ask' },
          request: 'u-1',
          live,
        },
      }),
    ).toBe(
      '{"id":2,"seq":9,"op":{"op":"answer_ui","live":{"key":"k","generation":2},"request":"u-1",' +
        '"value":{"type":"ask","answers":[{"id":"q","selected":[1],"custom":null}]}}}',
    );
    expect(
      requestJson({
        id: 3,
        seq: 10,
        op: { op: 'sync_set', excluded: [], parts: { memory: true, sessions: false, omp: true }, project: 'p' },
      }),
    ).toBe(
      '{"id":3,"seq":10,"op":{"op":"sync_set","project":"p","parts":{"omp":true,"sessions":false,"memory":true},"excluded":[]}}',
    );
  });

  test('free-form values are written with sorted keys, as serde_json::Value does', () => {
    const op: Op = { op: 'omp_set', key: 'k', value: { z: 1, a: [{ y: null, b: 'x' }], m: { d: true, c: 0.5 } } };
    expect(requestJson({ id: 4, seq: 11, op })).toBe(
      '{"id":4,"seq":11,"op":{"op":"omp_set","key":"k","value":{"a":[{"b":"x","y":null}],"m":{"c":0.5,"d":true},"z":1}}}',
    );
    const proto = JSON.parse('{"__proto__":{"x":1},"b":2}');
    expect(requestJson({ id: 5, seq: 12, op: { op: 'omp_set', key: 'k', value: proto } })).toBe(
      '{"id":5,"seq":12,"op":{"op":"omp_set","key":"k","value":{"__proto__":{"x":1},"b":2}}}',
    );
  });
});

describe('slice-4 classes, journaling and bounds', () => {
  const live = { key: 'k', generation: 1 };

  test('classes and journaling mirror Op::class / Op::journaled', () => {
    expect(opClass({ op: 'last_reply', session: 's' })).toBe('view');
    expect(opClass({ op: 'unpair' })).toBe('view');
    expect(opJournaled({ op: 'unpair' })).toBe(false);
    for (const op of [
      { op: 'upload_begin', name: 'a', mime: 'b', size: 1 },
      { op: 'upload_chunk', upload: 'x', offset: 0, data: '' },
      { op: 'upload_cancel', upload: 'x' },
      { op: 'update_check' },
    ] satisfies Op[]) {
      expect(opClass(op)).toBe('control');
      expect(opJournaled(op)).toBe(false);
    }
    expect(opJournaled({ op: 'compose', live, text: 'x', attachments: [], mode: 'steer' })).toBe(true);
    expect(opClass({ op: 'backup_connect' })).toBe('manage');
    expect(opJournaled({ op: 'backup_connect' })).toBe(true);
    const control = { control: true, manage: false };
    expect(opAllowed({ op: 'answer_ui', live, request: 'u-1', value: { type: 'cancel' } }, control)).toBe(true);
    expect(opAllowed({ op: 'omp_reset', key: 'k' }, control)).toBe(false);
  });

  test('Op::check and Feed::check bounds', () => {
    const tree = (limit: number): Request => ({
      id: 1,
      seq: null,
      op: { op: 'tree', session: 's', filter: 'default', limit },
    });
    const days = (n: number): Request => ({ id: 1, seq: null, op: { op: 'usage_activity', days: n } });
    const chunk = (n: number): Request => ({
      id: 1,
      seq: null,
      op: { op: 'upload_chunk', upload: 'x', offset: 0, data: 'A'.repeat(n) },
    });
    expect(MAX_TRANSFER_CHUNK_B64).toBe(Math.ceil(MAX_TRANSFER_CHUNK / 3) * 4);
    for (const ok of [tree(1), tree(MAX_TREE_LIMIT), days(1), days(MAX_ACTIVITY_DAYS), chunk(MAX_TRANSFER_CHUNK_B64)]) {
      expect(checkRequest(ok)).toBeNull();
    }
    for (const bad of [tree(0), tree(MAX_TREE_LIMIT + 1), days(0), days(MAX_ACTIVITY_DAYS + 1), chunk(MAX_TRANSFER_CHUNK_B64 + 1)]) {
      expect(checkRequest(bad)).not.toBeNull();
    }
    expect(checkFeed({ feed: 'inventory', limit: MAX_INVENTORY_LIMIT })).toBeNull();
    expect(checkFeed({ feed: 'inventory', limit: 0 })).not.toBeNull();
    expect(checkFeed({ feed: 'inventory', limit: MAX_INVENTORY_LIMIT + 1 })).not.toBeNull();
    expect(checkRequest({ id: 1, seq: null, op: { op: 'download', download: 'x', offset: -1 } })).not.toBeNull();
    expect(
      checkRequest({ id: 1, seq: 2, op: { op: 'app_update', step: 'later' as 'apply' } }),
    ).not.toBeNull();
  });

  test('the builder gives seqs to journaled slice-4 ops only', () => {
    const builder = new RequestBuilder({ next_seq: 40 });
    expect(builder.build({ op: 'upload_cancel', upload: 'x' }).seq).toBeNull();
    expect(builder.build({ op: 'backup_run' }).seq).toBe(40);
    expect(builder.build({ op: 'presence', visible: false }).seq).toBeNull();
    expect(builder.nextSeq).toBe(41);
  });
});

describe('slice-4 gateway messages validate', () => {
  const decoders = { reply: decodeReply, event: decodeEvent, welcome: decodeWelcome } as const;

  for (const type of ['reply', 'event', 'welcome'] as const) {
    for (const vector of messages(type)) {
      test(`${type} ${vector.case}`, () => {
        const value = decoders[type](utf8(vector.json));
        const parsed: unknown = JSON.parse(vector.json);
        expect(parsed).toEqual(value);
        // Same keys in the same order as Rust wrote them, additive fields only when present.
        expect(JSON.stringify(value)).toBe(JSON.stringify(parsed));
      });
    }
  }

  test('the additive fields are absent when the gateway omits them', () => {
    const welcome = decodeWelcome(
      utf8(
        '{"protocol":1,"gateway_version":"0.9.0","epoch":"e","device":"d","name":"n",' +
          '"permissions":{"control":true,"manage":false},"next_seq":1,"limits":{"max_message":1,' +
          '"window_bytes":1,"window_messages":1,"max_inflight":1,"max_views":1,"max_feeds":1},"features":[]}',
      ),
    );
    expect('push_key' in welcome).toBe(false);
    const event = decodeEvent(
      utf8(
        '{"type":"feed","feed":{"feed":"transcript","session":"s","agent":null,"tail":1},"value":{"feed":"transcript",' +
          '"start":0,"items":[{"type":"tool_result","call_id":"c","name":"n","text":"","is_error":false,"truncated":false}],"reset":true}}',
      ),
    );
    expect(event).toEqual({
      type: 'feed',
      feed: { feed: 'transcript', session: 's', agent: null, tail: 1 },
      value: {
        feed: 'transcript',
        start: 0,
        items: [{ type: 'tool_result', call_id: 'c', name: 'n', text: '', is_error: false, truncated: false }],
        reset: true,
      },
    });
  });

  test('malformed slice-4 values are refused', () => {
    const bad = [
      '{"id":1,"ok":{"type":"chunk","data":"x"}}',
      '{"id":1,"ok":{"type":"tree","nodes":[{"id":"a"}],"active_leaf":null,"next_cursor":null,"truncated":false}}',
      '{"id":1,"ok":{"type":"outcome","outcome":{"state":"done","result":{"type":"restore_plan","handle":1,"plan":{"type":"cloud"},"truncated":false}}}}',
      '{"id":1,"ok":{"type":"omp_settings","groups":[{"id":"g","label":"G","entries":[{"key":"k","kind":{"type":"color"},"description":"","value":null,"default":null,"modified":false,"secret":false,"set":false}]}],"truncated":false}}',
    ];
    for (const json of bad) expect(() => decodeReply(utf8(json))).toThrow(ApiDecodeError);
    expect(() =>
      decodeEvent(utf8('{"type":"feed","feed":{"feed":"device"},"value":{"feed":"device","name":"n"}}')),
    ).toThrow(ApiDecodeError);
  });
});

test('slice-4 rejected requests are never sent as such', () => {
  // Each fails checkRequest the way the gateway would refuse it, except unknown fields, which
  // the canonical encoding drops (the typed request cannot carry them).
  for (const vector of vectors.rejected_requests) {
    const request: Request = JSON.parse(vector.json);
    if (vector.case.startsWith('unknown field')) {
      expect(requestJson(request)).not.toBe(vector.json);
    } else {
      expect(checkRequest(request)).not.toBeNull();
    }
  }
});
